\set ON_ERROR_STOP on
begin;
insert into auth.users(id,email,email_confirmed_at) values('b7000000-0000-4000-8000-000000000001','logistics-owner@example.invalid',now()),('b7000000-0000-4000-8000-000000000002','logistics-staff@example.invalid',now()),('b7000000-0000-4000-8000-000000000003','logistics-cashier@example.invalid',now());
set local role authenticated;
set local "request.jwt.claim.sub"='b7000000-0000-4000-8000-000000000001';
select set_config('test.b7_org',organization_id::text,true),set_config('test.b7_source',branch_id::text,true) from public.bootstrap_organization('Logistics fixture','Owner fixture');
select test.assert(public.get_branch_management_context(test.id('b7_org'))->>'can_create'='true','Owner sees genuine branch create capability');
select set_config('test.b7_branch_action',public.save_branch(test.id('b7_org'),'b7100000-0000-4000-8000-000000000001',null,null,'Destination','DEST',null,true,'Create delivery destination')::text,true);
select set_config('test.b7_dest',current_setting('test.b7_branch_action')::jsonb->'branch'->>'id',true);
select test.assert(public.save_branch(test.id('b7_org'),'b7100000-0000-4000-8000-000000000001',null,null,'Destination','DEST',null,true,'Create delivery destination')=current_setting('test.b7_branch_action')::jsonb,'Lost branch creation response replays exact immutable action');
select test.expect_error($q$select public.save_branch(test.id('b7_org'),'b7100000-0000-4000-8000-000000000001',null,null,'Changed','DEST',null,true,'Create delivery destination')$q$,'23505','Branch request cannot change payload');
select test.expect_error($q$select public.save_branch(test.id('b7_org'),gen_random_uuid(),test.id('b7_dest'),2,'Destination','DEST',null,true,'Stale branch revision')$q$,'40001','Branch CAS rejects stale update');
select test.expect_error($q$select public.save_branch(test.id('b7_org'),gen_random_uuid(),test.id('b7_dest'),1,'Destination','NEWCODE',null,true,'Changing identifier')$q$,'22023','Branch code never changes');
select set_config('test.b7_product',(public.save_product(test.id('b7_org'),null,null,'{"name":"Counted stock","sku":"B7-A","price_minor":100,"unit":"each"}','Create counted product')->>'id'),true);
select public.receive_stock(test.id('b7_org'),test.id('b7_source'),'b7100000-0000-4000-8000-000000000002',jsonb_build_array(jsonb_build_object('product_id',test.id('b7_product'),'quantity',10,'expected_revision',1)),null,null,'Ten physical source units');
select test.expect_error($q$select public.save_product(test.id('b7_org'),test.id('b7_product'),1,'{"unit":"box"}','Unsafe unit conversion')$q$,'22023','Referenced stock units cannot be reinterpreted');
select test.expect_error($q$select public.save_branch(test.id('b7_org'),gen_random_uuid(),test.id('b7_source'),1,'Main Branch','MAIN',null,false,'Close stocked branch')$q$,'23514','Branch deactivation cannot strand on-hand goods');
select set_config('test.b7_input',jsonb_build_array(jsonb_build_object('product_id',test.id('b7_product'),'quantity',6,'expected_revision',1))::text,true);
select test.expect_error($q$select public.dispatch_stock_transfer(test.id('b7_org'),test.id('b7_source'),test.id('b7_dest'),gen_random_uuid(),current_setting('test.b7_input')::jsonb,null,'Without physical proof',false)$q$,'22023','Dispatch requires explicit physical confirmation');
select set_config('test.b7_dispatch',public.dispatch_stock_transfer(test.id('b7_org'),test.id('b7_source'),test.id('b7_dest'),'b7100000-0000-4000-8000-000000000003',current_setting('test.b7_input')::jsonb,'Truck reference','Six units physically dispatched',true)::text,true);
select set_config('test.b7_transfer',current_setting('test.b7_dispatch')::jsonb->'document'->>'id',true);
select set_config('test.b7_item',current_setting('test.b7_dispatch')::jsonb->'document'->'items'->0->>'item_id',true);
select test.assert(public.dispatch_stock_transfer(test.id('b7_org'),test.id('b7_source'),test.id('b7_dest'),'b7100000-0000-4000-8000-000000000003',current_setting('test.b7_input')::jsonb,'Truck reference','Six units physically dispatched',true)=current_setting('test.b7_dispatch')::jsonb,'Dispatch replays original movement and action');
select test.assert((public.get_stock_transfer(test.id('b7_org'),test.id('b7_dest'),test.id('b7_transfer'))->'items'->0->>'remaining')::int=6,'Goods are tracked in transit after dispatch');
select test.assert(public.get_stock_transfer(test.id('b7_org'),test.id('b7_dest'),test.id('b7_transfer'))->>'status'='in_transit','No destination receipt is invented');
select test.expect_error($q$select public.save_branch(test.id('b7_org'),gen_random_uuid(),test.id('b7_dest'),1,'Destination','DEST',null,false,'Close transit destination')$q$,'23514','Empty destination still cannot deactivate with transit goods');
select set_config('test.b7_receipt',public.complete_stock_transfer(test.id('b7_org'),test.id('b7_dest'),'b7100000-0000-4000-8000-000000000004',test.id('b7_transfer'),1,'transfer.receive',jsonb_build_array(jsonb_build_object('item_id',test.id('b7_item'),'quantity',4,'expected_revision',1)),null,'Four units physically counted',true)::text,true);
select test.assert(public.get_stock_transfer(test.id('b7_org'),test.id('b7_dest'),test.id('b7_transfer'))->>'status'='partially_completed','Partial receipt preserves outstanding transit goods');
select test.expect_error($q$select public.complete_stock_transfer(test.id('b7_org'),test.id('b7_dest'),gen_random_uuid(),test.id('b7_transfer'),2,'transfer.receive',jsonb_build_array(jsonb_build_object('item_id',test.id('b7_item'),'quantity',3,'expected_revision',1)),null,'Too many received',true)$q$,'23514','Partial receipt cannot exceed remaining quantity');
select test.expect_error($q$select public.complete_stock_transfer(test.id('b7_org'),test.id('b7_source'),gen_random_uuid(),test.id('b7_transfer'),1,'transfer.return',jsonb_build_array(jsonb_build_object('item_id',test.id('b7_item'),'quantity',2,'expected_revision',1)),null,'Stale return attempt',true)$q$,'40001','Receipt versus return uses expected transfer revision');
select set_config('test.b7_return',public.complete_stock_transfer(test.id('b7_org'),test.id('b7_source'),'b7100000-0000-4000-8000-000000000005',test.id('b7_transfer'),2,'transfer.return',jsonb_build_array(jsonb_build_object('item_id',test.id('b7_item'),'quantity',2,'expected_revision',1)),null,'Two goods physically returned',true)::text,true);
select test.assert(public.get_stock_transfer(test.id('b7_org'),test.id('b7_source'),test.id('b7_transfer'))->>'status'='completed','Mixed receipt and return completes only actual accounted goods');
select test.assert(jsonb_array_length(public.list_stock_transfer_events(test.id('b7_org'),test.id('b7_source'),test.id('b7_transfer')))=2,'Receipt and transit return remain immutable physical history');
reset role;
select test.assert((select quantity from private.stock_balances where branch_id=test.id('b7_source') and product_id=test.id('b7_product'))=6,'Source depletion plus actual return is exact');
select test.assert((select quantity from private.stock_balances where branch_id=test.id('b7_dest') and product_id=test.id('b7_product'))=4,'Destination gets only physically received quantities');
insert into public.organization_memberships(id,organization_id,user_id,role,status) values('b7200000-0000-4000-8000-000000000001',test.id('b7_org'),'b7000000-0000-4000-8000-000000000002','inventory_staff','active'),('b7200000-0000-4000-8000-000000000002',test.id('b7_org'),'b7000000-0000-4000-8000-000000000003','cashier','active');
insert into public.membership_branches(organization_id,membership_id,branch_id) values(test.id('b7_org'),'b7200000-0000-4000-8000-000000000001',test.id('b7_dest')),(test.id('b7_org'),'b7200000-0000-4000-8000-000000000002',test.id('b7_dest'));
set local role authenticated;
set local "request.jwt.claim.sub"='b7000000-0000-4000-8000-000000000002';
select test.assert(public.get_stock_transfer(test.id('b7_org'),test.id('b7_dest'),test.id('b7_transfer'))->'items'->0 ? 'balance_after'=false,'Destination-only staff cannot see source balances');
select test.assert(public.list_stock_transfer_events(test.id('b7_org'),test.id('b7_dest'),test.id('b7_transfer'))->0->'operation_id'='null'::jsonb,'Foreign-endpoint operation identity is redacted in history');
select test.expect_error($q$select public.dispatch_stock_transfer(test.id('b7_org'),test.id('b7_source'),test.id('b7_dest'),gen_random_uuid(),current_setting('test.b7_input')::jsonb,null,'Unauthorized source',true)$q$,'42501','Destination assignment alone cannot dispatch source stock');
select test.expect_error($q$select public.get_branch_management_context(test.id('b7_org'))$q$,'42501','Inventory staff cannot administer branches');
set local "request.jwt.claim.sub"='b7000000-0000-4000-8000-000000000003';
select test.expect_error($q$select public.list_stock_transfers(test.id('b7_org'),test.id('b7_dest'))$q$,'42501','Cashier cannot inspect operational transfer history');
set local "request.jwt.claim.sub"='b7000000-0000-4000-8000-000000000001';
select set_config('test.b7_supplier',(public.save_supplier(test.id('b7_org'),null,null,jsonb_build_object('name','Original supplier','branch_id',test.id('b7_source'),'active',true),'Create original supplier')->>'id'),true);
select set_config('test.b7_order',(public.create_purchase_order(test.id('b7_org'),test.id('b7_source'),'b7100000-0000-4000-8000-000000000006',test.id('b7_supplier'),1,1,'PHP',jsonb_build_array(jsonb_build_object('product_id',test.id('b7_product'),'expected_revision',1,'quantity',5,'unit_cost_minor',125)),null,'Original procurement cost') ->>'order_id'),true);
select set_config('test.b7_order_item',public.get_purchase_order(test.id('b7_org'),test.id('b7_source'),test.id('b7_order'))->'items'->0->>'id',true);
select set_config('test.b7_original_receipt',public.receive_purchase_order(test.id('b7_org'),test.id('b7_source'),'b7100000-0000-4000-8000-000000000007',test.id('b7_order'),1,jsonb_build_array(jsonb_build_object('order_item_id',test.id('b7_order_item'),'quantity',5,'expected_product_revision',1)),null,'Five actual purchased units')->'receipt'->>'id',true);
select set_config('test.b7_receipt_item',public.get_purchase_receipt_return_context(test.id('b7_org'),test.id('b7_source'),test.id('b7_original_receipt'))->'items'->0->>'item_id',true);
select set_config('test.b7_supplier_return',public.return_purchase_receipt(test.id('b7_org'),test.id('b7_source'),'b7100000-0000-4000-8000-000000000008',test.id('b7_original_receipt'),jsonb_build_array(jsonb_build_object('item_id',test.id('b7_receipt_item'),'quantity',3,'expected_revision',1)),null,'Three goods physically returned',true)::text,true);
select test.assert((current_setting('test.b7_supplier_return')::jsonb->'document'->>'total_minor')::bigint=375,'Supplier return preserves original recorded procurement cost');
select test.assert(current_setting('test.b7_supplier_return')::jsonb->'document'->>'currency'='PHP','Supplier return retains original currency without payment claims');
select test.assert((public.get_purchase_receipt_return_context(test.id('b7_org'),test.id('b7_source'),test.id('b7_original_receipt'))->'items'->0->>'returned')::int=3,'Cumulative supplier return projects original receipt quantities');
select test.expect_error($q$select public.return_purchase_receipt(test.id('b7_org'),test.id('b7_source'),gen_random_uuid(),test.id('b7_original_receipt'),jsonb_build_array(jsonb_build_object('item_id',test.id('b7_receipt_item'),'quantity',3,'expected_revision',1)),null,'Over original quantity',true)$q$,'23514','Cumulative return cannot exceed original received units');
select test.assert(public.return_purchase_receipt(test.id('b7_org'),test.id('b7_source'),'b7100000-0000-4000-8000-000000000008',test.id('b7_original_receipt'),jsonb_build_array(jsonb_build_object('item_id',test.id('b7_receipt_item'),'quantity',3,'expected_revision',1)),null,'Three goods physically returned',true)=current_setting('test.b7_supplier_return')::jsonb,'Unknown supplier return replays original exact action');
select test.assert(jsonb_array_length(public.list_purchase_returns(test.id('b7_org'),test.id('b7_source')))=1,'Return history contains genuine recorded action');
select test.expect_error($q$update public.purchase_returns set total_minor=0$q$,'42501','Clients cannot rewrite supplier return history');
select test.expect_error($q$delete from public.stock_transfers$q$,'42501','Clients cannot erase transfer evidence');
select set_config('test.b7_empty_action',public.save_branch(test.id('b7_org'),'b7100000-0000-4000-8000-000000000009',null,null,'Empty','EMPTY',null,true,'Create empty branch')::text,true);
select set_config('test.b7_empty',current_setting('test.b7_empty_action')::jsonb->'branch'->>'id',true);
select set_config('test.b7_deactivate',public.save_branch(test.id('b7_org'),'b7100000-0000-4000-8000-000000000010',test.id('b7_empty'),1,'Empty','EMPTY',null,false,'Archive resolved branch')::text,true);
select test.assert(current_setting('test.b7_deactivate')::jsonb->'branch'->>'active'='false','Resolved empty branch can be deactivated');
select test.assert(public.save_branch(test.id('b7_org'),'b7100000-0000-4000-8000-000000000010',test.id('b7_empty'),1,'Empty','EMPTY',null,false,'Archive resolved branch')=current_setting('test.b7_deactivate')::jsonb,'Deactivation replay works on inactive target');
select test.assert(jsonb_array_length(public.list_managed_branches(test.id('b7_org')))=3,'Maintenance reads include inactive branches');
select 'B7_LOGISTICS_FIXTURE='||jsonb_build_object('organization_id',test.id('b7_org'),'source_branch_id',test.id('b7_source'),'destination_branch_id',test.id('b7_dest'),'branch_action',current_setting('test.b7_branch_action')::jsonb,'dispatch',current_setting('test.b7_dispatch')::jsonb,'receipt',current_setting('test.b7_receipt')::jsonb,'transit_return',current_setting('test.b7_return')::jsonb,'supplier_return',current_setting('test.b7_supplier_return')::jsonb,'transfer',public.get_stock_transfer(test.id('b7_org'),test.id('b7_source'),test.id('b7_transfer')),'return_context',public.get_purchase_receipt_return_context(test.id('b7_org'),test.id('b7_source'),test.id('b7_original_receipt')),'inactive_action',current_setting('test.b7_deactivate')::jsonb)::text;
-- Fresh authorization also gates replay of previously accepted physical goods.
set local "request.jwt.claims"='{"sub":"b7000000-0000-4000-8000-000000000001","aal":"aal2"}';
select public.update_security_policy(test.id('b7_org'),gen_random_uuid(),1,10,true,'Require privileged logistics assurance');
set local "request.jwt.claims"='{"sub":"b7000000-0000-4000-8000-000000000001","aal":"aal1"}';
select test.expect_error($q$select public.list_managed_branches(test.id('b7_org'))$q$,'42501','Branch administration independently enforces current MFA');
select test.expect_error($q$select public.dispatch_stock_transfer(test.id('b7_org'),test.id('b7_source'),test.id('b7_dest'),'b7100000-0000-4000-8000-000000000003',current_setting('test.b7_input')::jsonb,null,'Six goods physically dispatched',true)$q$,'42501','Original transfer replay cannot bypass current MFA');
select test.expect_error($q$select public.get_purchase_receipt_return_context(test.id('b7_org'),test.id('b7_source'),test.id('b7_original_receipt'))$q$,'42501','Supplier cost context requires current privileged assurance');
set local "request.jwt.claims"='{"sub":"b7000000-0000-4000-8000-000000000001","aal":"aal2"}';
reset role;
update public.organization_memberships set status='disabled' where organization_id=test.id('b7_org') and user_id='b7000000-0000-4000-8000-000000000002';
set local "request.jwt.claim.sub"='b7000000-0000-4000-8000-000000000002';
set local "request.jwt.claims"='{"sub":"b7000000-0000-4000-8000-000000000002","aal":"aal1"}';
set local role authenticated;
select test.expect_error($q$select public.list_stock_transfers(test.id('b7_org'),test.id('b7_source'))$q$,'42501','Disabled former stock staff cannot inspect transfer history');
select test.expect_error($q$select public.return_purchase_receipt(test.id('b7_org'),test.id('b7_source'),'b7100000-0000-4000-8000-000000000008',test.id('b7_original_receipt'),jsonb_build_array(jsonb_build_object('item_id',test.id('b7_receipt_item'),'quantity',3,'expected_revision',1)),null,'Three goods physically returned',true)$q$,'42501','Disabled identity cannot recover accepted supplier action');
reset role;
update public.organization_memberships set status='active' where organization_id=test.id('b7_org') and user_id='b7000000-0000-4000-8000-000000000002';
set local "request.jwt.claim.sub"='b7000000-0000-4000-8000-000000000001';
set local "request.jwt.claims"='{"sub":"b7000000-0000-4000-8000-000000000001","aal":"aal2"}';
select test.assert(not has_table_privilege('service_role','public.branches','INSERT') and not has_column_privilege('service_role','public.branches','name','UPDATE'),'Service role cannot bypass branch locking via direct writes');
select test.assert(not has_table_privilege('service_role','public.products','UPDATE'),'Service role cannot bypass referenced product unit guard');
set local role authenticated;
select test.expect_error($q$select public.dispatch_stock_transfer(test.id('b7_org'),test.id('b7_source'),test.id('b7_dest'),gen_random_uuid(),jsonb_build_array(jsonb_build_object('product_id',test.id('b7_product'),'quantity',100,'expected_revision',1)),null,'Excessive physical depletion',true)$q$,'23514','Dispatch cannot introduce ordinary negative stock');
reset role;
select test.assert((select quantity from private.stock_balances where branch_id=test.id('b7_source') and product_id=test.id('b7_product'))=8,'Rejected excessive dispatch leaves supplier-return-adjusted stock unchanged');
select test.assert((select count(*) from public.stock_transfers where organization_id=test.id('b7_org'))=1,'Rejected dispatch leaves no immutable transfer document');
rollback;
